mapper.select:
/* selectLoginHisList */ SELECT user_log_sn, user_id, login_date, ip_addr, lang_cd FROM SYS_USER_LOGIN_LOG WHERE 1=1
AND user_id = #{user_id}
ORDER BY login_date DESC

/* selectApiHisList */
SELECT 
	api_exe_log_sn,
	api_id,
	exe_dtm,
	user_id,
	api_exe_url,
	mthd_tp_cd,
	ip_addr,
	lang_cd,
	svr_ip_addr,
	inp_param_txt

		,trace_id


		,http_status


		,elapsed_ms

FROM SYS_API_EXE_LOG
WHERE 1=1

	AND api_id = #{api_id}


	AND user_id = #{user_id}


	AND api_exe_url = #{api_exe_url}


	AND api_exe_url LIKE CONCAT('%', #{api_exe_url_keyword}, '%')


	AND mthd_tp_cd = #{mthd_tp_cd}


	AND ip_addr = #{ip_addr}


	AND exe_dtm >= #{start_exe_dtm}


	AND exe_dtm <= #{end_exe_dtm}


	AND trace_id = #{trace_id}


	AND http_status = #{http_status}


	AND http_status >= 400


	AND elapsed_ms >= #{min_elapsed_ms}


	AND elapsed_ms <= #{max_elapsed_ms}


	AND elapsed_ms >= #{slow_threshold_ms}

ORDER BY exe_dtm DESC, api_exe_log_sn DESC
LIMIT #{limit}
OFFSET #{offset}

/* selectApiHisCount */
SELECT COUNT(1)
FROM SYS_API_EXE_LOG
WHERE 1=1

	AND api_id = #{api_id}


	AND user_id = #{user_id}


	AND api_exe_url = #{api_exe_url}


	AND api_exe_url LIKE CONCAT('%', #{api_exe_url_keyword}, '%')


	AND mthd_tp_cd = #{mthd_tp_cd}


	AND ip_addr = #{ip_addr}


	AND exe_dtm >= #{start_exe_dtm}


	AND exe_dtm <= #{end_exe_dtm}


	AND trace_id = #{trace_id}


	AND http_status = #{http_status}


	AND http_status >= 400


	AND elapsed_ms >= #{min_elapsed_ms}


	AND elapsed_ms <= #{max_elapsed_ms}


	AND elapsed_ms >= #{slow_threshold_ms}

SELECT api_exe_url, mthd_tp_cd, COUNT(1) AS error_count FROM SYS_API_EXE_LOG WHERE 1=1
AND exe_dtm >= #{start_exe_dtm}
AND exe_dtm <= #{end_exe_dtm}
AND http_status >= 400
AND 1 = 0
GROUP BY api_exe_url, mthd_tp_cd ORDER BY error_count DESC, api_exe_url ASC LIMIT #{summary_limit}

SELECT api_exe_url, mthd_tp_cd, COUNT(1) AS slow_count, ROUND(AVG(elapsed_ms), 2) AS avg_elapsed_ms, MAX(elapsed_ms) AS max_elapsed_ms FROM SYS_API_EXE_LOG WHERE 1=1
AND exe_dtm >= #{start_exe_dtm}
AND exe_dtm <= #{end_exe_dtm}
AND elapsed_ms >= #{slow_threshold_ms}
AND 1 = 0
GROUP BY api_exe_url, mthd_tp_cd ORDER BY max_elapsed_ms DESC, avg_elapsed_ms DESC, api_exe_url ASC LIMIT #{summary_limit}

SELECT exe_dtm, user_id, api_exe_url, mthd_tp_cd,
trace_id,
'' AS trace_id,
COALESCE(http_status, 0) AS http_status,
0 AS http_status,
elapsed_ms
0 AS elapsed_ms
FROM SYS_API_EXE_LOG WHERE 1=1
AND exe_dtm >= #{start_exe_dtm}
AND exe_dtm <= #{end_exe_dtm}
AND elapsed_ms >= #{slow_threshold_ms}
AND 1 = 0
ORDER BY elapsed_ms DESC, exe_dtm DESC, api_exe_log_sn DESC LIMIT #{summary_limit}

/* selectDetailBatHis */
SELECT rslt_txt
FROM sys_batch_run_his
WHERE run_sn = #{id}

mapper.insert:
/* insertApiExecutionLog */ INSERT INTO SYS_API_EXE_LOG ( api_id, exe_dtm, user_id, api_exe_url, mthd_tp_cd, ip_addr, lang_cd, svr_ip_addr, inp_param_txt
,trace_id
,http_status
,elapsed_ms
) VALUES ( #{api_id}, #{exe_dtm}, #{sess_user_id}, #{url}, #{method}, #{ip}, #{sess_lang_cd}, #{server_ip}, #{input_param}
,#{trace_id}
,#{http_status}
,#{elapsed_ms}
)

mapper.select:
/* selectApiByUrl */
SELECT api_id
FROM SYS_API
WHERE api_url = #{url}
LIMIT 1
